parameters.jsCode:
const from = (query.from_currency || "").toUpperCase();
const to = (query.to_currency || "").toUpperCase();

if (!from || !to) {
  return "দুঃখিত, currency code পাওয়া যায়নি।";
}

const url = `https://open.er-api.com/v6/latest/${from}`;
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: url,
  json: true
});

if (!response.rates || !response.rates[to]) {
  return `"${from}" থেকে "${to}"-তে রূপান্তরের তথ্য পাওয়া যায়নি। সঠিক currency code (যেমন USD, BDT, EUR) ব্যবহার করুন।`;
}

return JSON.stringify({
  from: from,
  to: to,
  rate: response.rates[to],
  last_updated: response.time_last_update_utc || "N/A"
});

