{
  "type": "object",
  "properties": {
    "from_currency": {
      "type": "string",
      "description": "Source currency code, e.g. USD"
    },
    "to_currency": {
      "type": "string",
      "description": "Target currency code, e.g. BDT"
    }
  },
  "required": ["from_currency", "to_currency"]
}
